// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	logHeader := caddyhttp.LoggableHTTPHeader{
		Header: http.Header{"Cookie": []string{in.String}},
	}
	logReq := caddyhttp.LoggableHTTPRequest{
		Request: &http.Request{Header: logHeader.Header},
	}

	originHeader := logHeader.Header
	if logReq.Request != nil && logReq.Request.Header != nil {
		originHeader = logReq.Request.Header
	}

	originRequest := http.Request{Header: originHeader}
	cookies := originRequest.Cookies()
	transformedRequest := http.Request{Header: make(http.Header)}

OUTER:
	for _, c := range cookies {
		for _, a := range m.Actions {
			if c.Name != a.Name {
				continue
			}

			switch a.Type {
			case replaceAction:
				c.Value = a.Value
				transformedRequest.AddCookie(c)
				continue OUTER

			case hashAction:
				c.Value = hash(c.Value)
				transformedRequest.AddCookie(c)
				continue OUTER

			case deleteAction:
				continue OUTER
			}
		}

		transformedRequest.AddCookie(c)
	}

	ops := headers.HeaderOps{
		Delete: []string{"Cookie"},
		Set:    http.Header{"Cookie": transformedRequest.Header["Cookie"]},
		Add:    http.Header{},
	}
	resultHeader := make(http.Header)
	for _, name := range ops.Delete {
		resultHeader.Del(name)
	}
	for name, vals := range ops.Set {
		if len(vals) == 0 {
			continue
		}
		resultHeader[name] = vals
	}
	for name, vals := range ops.Add {
		for _, val := range vals {
			resultHeader.Add(name, val)
		}
	}

	in.String = resultHeader.Get("Cookie")
	return in
}

// applyFieldFilter reports whether the field was filtered and added to the
// underlying encoder.
func (CookieFilter) applyFieldFilter(fe FilterEncoder, key string, value any) bool {
	filter, ok := fe.Fields[fe.keyPrefix+key]
	if !ok {
		return false
	}
	filter.Filter(zap.Any(key, value)).AddTo(fe.wrapped)
	return true
}

