package logging

import (
	"bytes"
	"strings"
	"testing"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
	"go.uber.org/zap"
	"go.uber.org/zap/buffer"
	"go.uber.org/zap/zapcore"
)

func TestCookieFilterEndToEnd(t *testing.T) {
	var config = `
	{
		wrap json
		fields {
			request>headers>Cookie cookie {
				replace sessionid REDACTED
			}
		}
	}`

	enc, err := caddyfile.UnmarshalModule(caddyfile.NewTestDispenser("filter"+config), "caddy.logging.encoders.filter")
	if err != nil {
		t.Fatal(err)
	}
	filterEnc := enc.(zapcore.Encoder)
	ctx := caddy.Context{}
	if err := filterEnc.(caddy.Provisioner).Provision(ctx); err != nil {
		t.Fatal(err)
	}

	req := caddyhttp.TestRequest()
	req.Header.Set("Cookie", "myvalue=1; sessionid=ST1LLh3r3")

	logger := zap.New(zapcore.NewCore(filterEnc, &bufferAdder{new(buffer.Buffer)}, zapcore.InfoLevel))
	logger.Info("handled request", zap.Object("request", caddyhttp.LoggableHTTPRequest{Request: req, ShouldLogCredentials: true}))

	out := logger.(*zap.Logger).Check(zapcore.InfoLevel, "").Write(...)
}

type bufferAdder struct {
	*buffer.Buffer
}

func TestCookieFilterDirect(t *testing.T) {
	f := CookieFilter{[]cookieFilterAction{{replaceAction, "sessionid", "REDACTED"}}}
	out := f.Filter(zap.Array("Cookie", caddyhttp.LoggableStringArray{"myvalue=1; sessionid=ST1LLh3r3"}))
	arr, ok := out.Interface.(caddyhttp.LoggableStringArray)
	if !ok || len(arr) != 1 || !strings.Contains(arr[0], "sessionid=REDACTED") || strings.Contains(arr[0], "ST1LLh3r3") {
		t.Fatalf("cookie not filtered: %v", out.Interface)
	}
}

